folder=r/'output'/('native-pick-displayed-layout-'+str(time.time_ns()));folder.mkdir();args=command('tests/world_selection_smoke.gd');start=time.time_ns();p=subprocess.run(args,cwd=r,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=140);log=p.stdout+p.stderr;(folder/'process.log').write_text(log,encoding='utf-8');receipt=json.loads(Path(args[args.index('--receipt')+1]).read_bytes());result=json.loads((r/'output/world-selection-result.json').read_bytes()) if (r/'output/world-selection-result.json').stat().st_mtime_ns>=start else {};proof={'exit':p.returncode,'command':args,'source_sha256':hashlib.sha256((r/'tests/world_selection_smoke.gd').read_bytes()).hexdigest(),'result':result,'receipt':receipt};(folder/'verification.json').write_text(json.dumps(proof,indent=2)+'\n',encoding='utf-8');print(json.dumps({'folder':str(folder),'exit':p.returncode,'result':result}));assert p.returncode==0 and result.get('checks')==41 and result.get('failures')==0 and not any(x in log for x in ['ERROR:','FAIL ','ObjectDB instances leaked','unclaimed string names']);assert receipt['exit']==0 and receipt['child_desktop_confirmed'] and not receipt['foreground_child_observed'] and receipt['job_closed'] and receipt['desktop_closed']
